#include <stdio.h>
#include <stdbool.h>

#define TABLE_SIZE 7
#define EMPTY -1
#define DELETED -2

int hashTable[TABLE_SIZE];

void initTable() {
    for (int i = 0; i < TABLE_SIZE; i++) {
        hashTable[i] = EMPTY;
    }
}

int hashFunction(int key) {
    return key % TABLE_SIZE;
}

// Insert using Linear Probing: (h(k) + i) % TABLE_SIZE
void insert(int key) {
    int index = hashFunction(key);
    for (int i = 0; i < TABLE_SIZE; i++) {
        int probeIndex = (index + i) % TABLE_SIZE;
        if (hashTable[probeIndex] == EMPTY || hashTable[probeIndex] == DELETED) {
            hashTable[probeIndex] = key;
            printf("Key %d inserted at index %d (Probes: %d)\n", key, probeIndex, i + 1);
            return;
        }
    }
    printf("Hash table is full! Cannot insert %d\n", key);
}

// Search using Linear Probing
int search(int key) {
    int index = hashFunction(key);
    for (int i = 0; i < TABLE_SIZE; i++) {
        int probeIndex = (index + i) % TABLE_SIZE;
        if (hashTable[probeIndex] == key) return probeIndex;
        if (hashTable[probeIndex] == EMPTY) return -1; // End of chain
    }
    return -1;
}

void display() {
    printf("\n--- Hash Table (Size %d) ---\n", TABLE_SIZE);
    for (int i = 0; i < TABLE_SIZE; i++) {
        if (hashTable[i] == EMPTY) printf("[%d] : EMPTY\n", i);
        else if (hashTable[i] == DELETED) printf("[%d] : DELETED\n", i);
        else printf("[%d] : %d\n", i, hashTable[i]);
    }
}

int main(void) {
    initTable();
    insert(10); // 10 % 7 = 3
    insert(17); // 17 % 7 = 3 (Collision! Probes to index 4)
    insert(24); // 24 % 7 = 3 (Collision! Probes to index 5)
    insert(15); // 15 % 7 = 1
    display();

    int key = 17;
    int foundIdx = search(key);
    if (foundIdx != -1) {
        printf("\nSearch: Key %d found at index %d.\n", key, foundIdx);
    } else {
        printf("\nSearch: Key %d not found.\n", key);
    }
    return 0;
}
